from notes.download import download_note
from notes.errors import AuthenticationRequired, NoteNotFound
from notes.store import Note, NoteStore

store = NoteStore([
    Note('note-alice', 'alice', 'Draft', 'First line\n便笺 café\n'),
    Note('note-bob', 'bob', 'Empty', ''),
])

# Cross-owner download must be denied (404), even though the SDK store returns it
for uid in (None, ''):
    try:
        download_note(store, uid, 'note-alice'); print('FAIL: no auth error')
    except AuthenticationRequired: print('ok: uid=%r -> AuthenticationRequired' % uid)

for uid, nid in [('alice', 'note-bob'), ('bob', 'note-alice')]:
    try:
        download_note(store, uid, nid); print('FAIL: cross-owner allowed')
    except NoteNotFound: print('ok: %s cannot read %s -> NoteNotFound' % (uid, nid))

# Exact text preservation
s = download_note(store, 'alice', 'note-alice')
assert s == 'First line\n便笺 café\n' and type(s) is str
print('ok: exact content, unicode + trailing newline preserved')
assert download_note(store, 'bob', 'note-bob') == ''
print('ok: empty content preserved')
